def faktoriyel(n):
    if n <= 1:
        return 1
    return n * faktoriyel(n - 1)
print(faktoriyel(4))

hafiza = {}

def fib(n):
    if n in hafiza:
        return hafiza[n]
    if n < 2:
        sonuc = n
    else:
        sonuc = fib(n - 1) + fib(n - 2)
    hafiza[n] = sonuc
    return sonuc

print(fib(40))
